package com.bank.http;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;

@Service
@Slf4j
public class HttpClientService {

    private final HttpClient client = HttpClient.newBuilder()
        .version(HttpClient.Version.HTTP_2)       // prefer HTTP/2
        .connectTimeout(Duration.ofSeconds(10))    // connection timeout
        .followRedirects(HttpClient.Redirect.NORMAL)
        .build();

    // ═══ SYNC: send() — blocks until response ═══
    public String fetchSync(String url) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .timeout(Duration.ofSeconds(30))       // request timeout
            .header("Accept", "application/json")
            .GET()
            .build();

        HttpResponse<String> response = client.send(request,
            HttpResponse.BodyHandlers.ofString());  // blocks here!

        log.info("[SYNC] Status: {}, Body length: {}", response.statusCode(), response.body().length());
        return response.body();
    }

    // ═══ ASYNC: sendAsync() — returns CompletableFuture ═══
    public CompletableFuture<String> fetchAsync(String url) {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .timeout(Duration.ofSeconds(30))
            .GET()
            .build();

        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
            .thenApply(HttpResponse::body)                     // extract body
            .exceptionally(ex -> "Error: " + ex.getMessage()); // handle error
    }

    // ═══ POST with JSON body ═══
    public String postJson(String url, String jsonBody) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(jsonBody))
            .build();

        return client.send(request, HttpResponse.BodyHandlers.ofString()).body();
    }
}
