package com.bank.http;

import org.junit.jupiter.api.Test;
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import static org.assertj.core.api.Assertions.*;

class HttpClientTest {

    @Test void clientBuilderCreatesInstance() {
        HttpClient client = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_2)
            .connectTimeout(Duration.ofSeconds(5))
            .build();
        assertThat(client).isNotNull();
        assertThat(client.version()).isEqualTo(HttpClient.Version.HTTP_2);
    }

    @Test void requestBuilderCreatesGetRequest() {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("https://api.example.com/trades"))
            .header("Accept", "application/json")
            .GET()
            .build();
        assertThat(request.method()).isEqualTo("GET");
        assertThat(request.uri().toString()).contains("trades");
    }

    @Test void requestBuilderCreatesPostRequest() {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("https://api.example.com/trades"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString("{\"symbol\":\"RELIANCE\"}"))
            .build();
        assertThat(request.method()).isEqualTo("POST");
    }
}
