package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.URI;
import static org.assertj.core.api.Assertions.assertThat;

class HttpClientTest {

    @Test
    void buildsClientAndRequest() {
        HttpClient client = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_2)   // HTTP/2 by default
            .build();
        HttpRequest req = HttpRequest.newBuilder(URI.create("https://bank/api/v1/transfers"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString("{\"amount\":50000}"))
            .build();

        assertThat(client.version()).isEqualTo(HttpClient.Version.HTTP_2);
        assertThat(req.method()).isEqualTo("POST");
        assertThat(req.uri().getPath()).isEqualTo("/api/v1/transfers");
    }
}
